     "title": "8月6日国内四大证券报纸、重要财经媒体头版头条内容精华摘要",
     "url": "http://finance.eastmoney.com/news/1344,202608053832922728.html",
     "time": "08-06 06:03",
     "ts": 1785967415,
     "summary": "8月6日(星期四)，今日报刊头条主要内容精华如下： 中国证券报 可转债发行节奏加快 新券上市表现亮眼 8月5日，N江农转上市首日大涨57.30%，三鑫转债公布网上中签率情况。今年以来，可转债市场供给显著放量，发行数量及规模较去年同期大幅增长，网上打新中签率走低。与此同时，新券上市行情火热，多只转债上市首日触及57.30%涨幅上限。专家表示，受供需错配等因素影响转债高估值或短期延续，转债市场或将跟随权益市场维持震荡格局。 人民币国债在港常态化发行 拓宽外资配置中国资产渠道 8月",
